def remaining_gifts_after_k(gifts,k):
    import heapq
    heap=[-value for value in gifts];heapq.heapify(heap)
    for _ in range(k):
        largest=-heapq.heappop(heap);heapq.heappush(heap,-__import__('math').isqrt(largest))
    return -sum(heap)

